 Material Surface(Color color,bool tiled=false){var m=Own(new Material(definition.surfaceShader));m.color=color;m.SetFloat("_Glossiness",.12f);if(tiled){var texture=Own(new Texture2D(64,64,TextureFormat.RGB24,false));texture.filterMode=FilterMode.Point;texture.wrapMode=TextureWrapMode.Repeat;for(int y=0;y<64;y++)for(int x=0;x<64;x++){int offset=(y/8%2)*8;bool joint=y%8==0||(x+offset)%16==0;float noise=((x*19+y*37)%17)/170f;texture.SetPixel(x,y,Color.white*(joint?.67f:.91f+noise*.5f));}texture.Apply();m.mainTexture=texture;m.mainTextureScale=new Vector2(4,4);}return m;}
