 Landmarks["市场"]=new Vector3(-5,0,6.2f);Landmarks["市政厅"]=new Vector3(6,0,-2.5f);Landmarks["伙伴"]=new Vector3(5,0,5.8f);Landmarks["船坞"]=new Vector3(-6,0,-2);Landmarks["产业园"]=new Vector3(7.5f,0,4.8f);Landmarks["码头"]=new Vector3(-3,0,-5);
 for(int i=0;i<5;i++){Box("Mooring post",new Vector3(-1.7f,0,-5+i*3),new Vector3(.16f,1.5f,.16f),wood,false);}Boat(new Vector3(.3f,-.45f,-4));}
 void Bridge(){int n=24;var vertices=new List<Vector3>();var triangles=new List<int>();var uv=new List<Vector2>();for(int i=0;i<=n;i++){float t=i/(float)n,x=Mathf.Lerp(-3.3f,3.3f,t),y=Mathf.Sin(t*Mathf.PI)*1.4f;vertices.Add(new Vector3(x,y,0));vertices.Add(new Vector3(x,y,2.5f));uv.Add(new Vector2(t*4,0));uv.Add(new Vector2(t*4,1));if(i<n){int a=i*2;triangles.AddRange(new[]{a,a+1,a+2,a+1,a+3,a+2});}if(i%2==0)for(int side=0;side<2;side++){Box("Bridge balustrade",new Vector3(x,y+.28f,side==0?-.1f:2.6f),new Vector3(.47f,.56f,.3f),stone,false);Box("Arch stone voussoir",new Vector3(x,y-.22f,side==0?0:2.5f),new Vector3(.3f,.45f,.32f),wall,false);}}
 var mesh=Own(new Mesh());mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.SetUVs(0,uv);mesh.RecalculateNormals();var go=new GameObject("Walkable arched stone bridge",typeof(MeshFilter),typeof(MeshRenderer),typeof(MeshCollider));go.layer=FloorLayer;go.transform.SetParent(transform);go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshRenderer>().sharedMaterial=stone;go.GetComponent<MeshCollider>().sharedMesh=mesh;}
