 void Card(string name,int index,Vector3 p,float width,Color tint,bool block){var rect=buildings.rects[index];var mat=SpriteMaterial(definition.buildingAtlas,rect,tint);var go=Quad(name,transform,mat,width,width*rect.height/rect.width);go.transform.position=p;go.transform.rotation=View.transform.rotation;Blob(p,width*.75f,.85f);if(block)obstacles.Add(new Rect(p.x-width*.30f,p.z-.2f,width*.60f,1.5f));}
 Transform Blob(Vector3 p,float width,float depth){var tex=Own(new Texture2D(32,32,TextureFormat.RGBA32,false));for(int y=0;y<32;y++)for(int x=0;x<32;x++){float d=new Vector2((x-15.5f)/16,(y-15.5f)/16).magnitude;tex.SetPixel(x,y,new Color(.05f,.04f,.025f,Mathf.Clamp01(1-d)*.36f));}tex.Apply();var m=Own(new Material(definition.atmosphereShader));m.mainTexture=tex;var q=Quad("Contact shadow",transform,m,width,depth);q.transform.position=p+new Vector3(0,.035f,-depth/2);q.transform.rotation=Quaternion.Euler(90,0,0);q.GetComponent<Renderer>().shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;return q.transform;}
 void Barrel(Vector3 p,float radius){var go=GameObject.CreatePrimitive(PrimitiveType.Cylinder);go.name="Coopered barrel";go.transform.SetParent(transform);go.transform.position=p+Vector3.up*.3f;go.transform.localScale=new Vector3(radius*2,.3f,radius*2);go.layer=ArtLayer;go.GetComponent<Renderer>().sharedMaterial=wood;Destroy(go.GetComponent<Collider>());for(int j=0;j<2;j++){var band=GameObject.CreatePrimitive(PrimitiveType.Cylinder);band.transform.SetParent(go.transform,false);band.transform.localPosition=new Vector3(0,j==0?-.65f:.65f,0);band.transform.localScale=new Vector3(1.04f,.05f,1.04f);band.layer=ArtLayer;band.GetComponent<Renderer>().sharedMaterial=metal;Destroy(band.GetComponent<Collider>());}}
 void Crates(Vector3 p){for(int i=0;i<5;i++){Vector3 q=p+new Vector3(i%3*.5f,i/3*.5f,0);Box("Cargo crate",q+Vector3.up*.25f,Vector3.one*.48f,wood,false);Box("Crate strap",q+new Vector3(0,.25f,-.245f),new Vector3(.07f,.48f,.02f),metal,false);}}
 void Mast(Vector3 p){Box("Foreground mast",p+Vector3.up*3,new Vector3(.14f,6,.14f),wood,false);Box("Yardarm",p+Vector3.up*4.7f,new Vector3(2.5f,.1f,.1f),wood,false);var material=Surface(new Color(.71f,.57f,.32f));var flag=Quad("Wind driven canvas",transform,material,1.7f,1.1f);flag.transform.position=p+new Vector3(.8f,3.5f,0);flag.transform.rotation=View.transform.rotation;flags.Add(flag.transform);}
 void Boat(Vector3 p){var go=Box("Gondola hull",p,new Vector3(.8f,.28f,3.4f),wood,false);go.transform.rotation=Quaternion.Euler(0,-12,0);Box("Gondola seat",p+Vector3.up*.25f,new Vector3(.9f,.18f,.35f),wood,false);}
 void Lantern(Vector3 p){Box("Quay lamp post",p+Vector3.up*.65f,new Vector3(.065f,1.3f,.065f),metal,false);var mat=Surface(new Color(.85f,.52f,.17f));mat.EnableKeyword("_EMISSION");mat.SetColor("_EmissionColor",new Color(2.8f,1.4f,.4f));Box("Warm lantern glass",p+Vector3.up*1.35f,new Vector3(.18f,.25f,.18f),mat,false);var go=new GameObject("Lantern light");go.transform.SetParent(transform);go.transform.position=p+Vector3.up*1.4f;var light=go.AddComponent<Light>();light.type=LightType.Point;light.color=new Color(1,.59f,.23f);light.intensity=1.7f;light.range=3;light.cullingMask=View.cullingMask;}
 void Particles(string name,Vector3 position,Vector3 size,Color color,float particleSize,float speed,int max){var go=new GameObject(name);go.transform.SetParent(transform);go.transform.position=position;go.layer=ArtLayer;var ps=go.AddComponent<ParticleSystem>();ps.Stop();var main=ps.main;main.startLifetime=10;main.startSpeed=speed;main.startSize=particleSize;main.startColor=color;main.maxParticles=max;main.simulationSpace=ParticleSystemSimulationSpace.World;var emission=ps.emission;emission.rateOverTime=max/5f;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=size;var velocity=ps.velocityOverLifetime;velocity.enabled=true;velocity.x=.1f;velocity.y=name=="Rain"?-5:name.Contains("leaves")?-.3f:name.Contains("smoke")?.18f:.015f;velocity.z=.04f;var mat=Own(new Material(definition.atmosphereShader));mat.SetFloat("_Mode",2);mat.SetInt("_SrcBlend",(int)UnityEngine.Rendering.BlendMode.SrcAlpha);mat.SetInt("_DstBlend",(int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);mat.SetInt("_ZWrite",0);mat.EnableKeyword("_ALPHABLEND_ON");mat.renderQueue=3000;var tex=Own(new Texture2D(16,16));for(int y=0;y<16;y++)for(int x=0;x<16;x++){float d=new Vector2((x-7.5f)/8,(y-7.5f)/8).magnitude;tex.SetPixel(x,y,new Color(1,1,1,Mathf.Clamp01(1-d)));}tex.Apply();mat.mainTexture=tex;go.GetComponent<ParticleSystemRenderer>().sharedMaterial=mat;if(name=="Rain"){go.GetComponent<ParticleSystemRenderer>().renderMode=ParticleSystemRenderMode.Stretch;go.GetComponent<ParticleSystemRenderer>().lengthScale=3;}ps.Play();ps.Simulate(5,true,false);ps.Play();atmosphere.Add(ps);}
 public void CycleWeather(){WeatherIndex=(WeatherIndex+1)%3;world.State.cities[definition.cityId].weatherPreset=WeatherIndex;ApplyWeather();}
 void ApplyWeather(){lens.fog=WeatherIndex==1?1.4f:.15f;sun.intensity=WeatherIndex==2?.65f:1.0f;water.SetFloat("_Wind",WeatherIndex==2?2.3f:1);foreach(var ps in atmosphere){var main=ps.main;if(ps.name=="Rain"){var rain=ps.emission;rain.enabled=WeatherIndex==2;if(WeatherIndex!=2)ps.Clear();}if(ps.name.Contains("mist")){main.startSize=WeatherIndex==1?3.2f:2.2f;var e=ps.emission;e.rateOverTime=WeatherIndex==1?5:1.4f;}}Status="天气："+WeatherName+" · 光照、雾与风同步变化";}
 public Vector2 Project(Vector3 p){var v=View.WorldToViewportPoint(p);return new Vector2(ScreenViewport.x+v.x*ScreenViewport.width,ScreenViewport.y+(1-v.y)*ScreenViewport.height);}
 public void GoTo(Vector3 target,string destination=""){path=grid.Path(Player.position,target);arrival=destination;Status=path.Count==0?"该位置无法到达，请选择石板路或桥面。":"正在沿道路行走…";}
 public bool HasPath(Vector3 from,Vector3 to)=>grid.Path(from,to).Count>0;
 void Update(){if(Player==null||world.Paused)return;float dt=Mathf.Min(Time.unscaledDeltaTime,.1f);animationTime+=dt;
 if(Input.GetMouseButtonDown(0)&&ScreenViewport.Contains(LiveGui.Mouse)&&!LiveGui.PointerOverControl){Vector2 p=LiveGui.Mouse;var ray=View.ViewportPointToRay(new Vector3((p.x-ScreenViewport.x)/ScreenViewport.width,1-(p.y-ScreenViewport.y)/ScreenViewport.height,0));if(Physics.Raycast(ray,out var hit,100,1<<FloorLayer))GoTo(hit.point);else Status="水域不可步行，请沿石阶、码头或拱桥前进。";}
 if(path.Count>0){Vector3 before=Player.position;Player.position=Vector3.MoveTowards(before,path[0],dt*2.7f*world.State.settings.moveSpeed);WalkedDistance+=Vector3.Distance(before,Player.position);Vector3 d=Player.position-before;Vector3 local=View.transform.InverseTransformDirection(d);if(d.sqrMagnitude>.000001f){float a=Mathf.Atan2(-local.x,-local.y)*Mathf.Rad2Deg;Facing=((Mathf.RoundToInt(a/45)+8)%8);}int frame=(int)(animationTime*7)%walks.rows;Rect uv=walks.rects[frame*8+Facing];walker.mainTextureScale=new Vector2(uv.width,uv.height);walker.mainTextureOffset=new Vector2(uv.x,uv.y);if(Vector3.Distance(Player.position,path[0])<.025f)path.RemoveAt(0);if(path.Count==0){Status="已到达。";if(arrival!=""){string next=arrival;arrival="";game.Change(next);}}}else{Rect uv=walks.rects[Facing];walker.mainTextureScale=new Vector2(uv.width,uv.height);walker.mainTextureOffset=new Vector2(uv.x,uv.y);}
 shadow.position=Player.position+new Vector3(0,.035f,-.18f);foreach(var flag in flags){var mesh=flag.GetComponent<MeshFilter>().sharedMesh;var vertices=mesh.vertices;for(int i=0;i<vertices.Length;i++)vertices[i].z=Mathf.Sin(Time.time*2.3f+vertices[i].x*4)*.10f;mesh.vertices=vertices;}
 }
